struct Calculator {
    int add(int a, int b) const { return a + b; }
    float operator()(double d) { return (float)d; }
};

// 1. Functor deduction (C++17/20 preferred)
using R1 = std::invoke_result_t<Calculator, double>;
// R1 is float

// 2. Member function pointer deduction
using MemFnPtr = decltype(&Calculator::add);
using R2 = std::invoke_result_t<MemFnPtr, Calculator const&, int, int>;
// R2 is int

